SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÜTLE VE AĞIRLIK KAVRAMLARININ KARŞILAŞTIRILMASI</text>\n  <rect x="25" y="48" width="310" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">KÜTLE (Değişmeyen Madde Miktarı)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" fill="#1e293b">• Cismi oluşturan madde miktarıdır.</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• Ölçüm Aracı: Eşit Kollu Terazi</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• Birimi: Kilogram (kg) veya Gram (g)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="12" fill="#1e293b">• Yönü yoktur, bir kuvvet değildir.</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">• Bulunulan yere göre DEĞİŞMEZ!</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#475569">(Dünya\'da 60 kg = Ay\'da 60 kg = Uzayda 60 kg)</text>\n\n  <rect x="365" y="48" width="310" height="192" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#be123c">AĞIRLIK (Yer Çekimi Kuvveti)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" fill="#1e293b">• Kütleye etki eden çekim kuvvetidir.</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Ölçüm Aracı: Dinamometre (Yaylı Kantar)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Birimi: Newton (N)  [1 kg ≈ 10 N]</text>\n  <text x="520" y="172" text-anchor="middle" font-size="12" fill="#1e293b">• Yönü yerin merkezine doğrudur.</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#e11d48">• Bulunulan yere göre DEĞİŞİR!</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#475569">(Dünya\'da 600 N ➔ Ay\'da 100 N)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÜNYA VE AY\'DA KÜTLE İLE AĞIRLIK ÖLÇÜMÜ (1:6 ORANI)</text>\n  <rect x="25" y="48" width="310" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <circle cx="95" cy="135" r="45" fill="#38bdf8" stroke="#0284c7" stroke-width="2"/>\n  <text x="95" y="132" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">DÜNYA</text>\n  <text x="95" y="150" text-anchor="middle" font-size="10" fill="#e0f2fe">Büyük Gök Cismi</text>\n  <text x="235" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Dünya\'daki Ölçümler</text>\n  <text x="235" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Kütle (m) = 12 kg</text>\n  <text x="235" y="136" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">Ağırlık (G) = 120 N</text>\n  <text x="235" y="166" text-anchor="middle" font-size="11" fill="#334155">1 kg kütle ≈ 10 N ağırlık</text>\n  <text x="235" y="192" text-anchor="middle" font-size="11" fill="#475569">Dinamometre yayı çok uzar</text>\n  <text x="235" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">(Örn: 6 bölmeli uzama)</text>\n\n  <rect x="365" y="48" width="310" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <circle cx="430" cy="135" r="24" fill="#cbd5e1" stroke="#64748b" stroke-width="2"/>\n  <text x="430" y="139" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">AY</text>\n  <text x="430" y="178" text-anchor="middle" font-size="10" fill="#475569">1/6 Çekim Gücü</text>\n  <text x="570" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ay\'daki Ölçümler</text>\n  <text x="570" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Kütle (m) = 12 kg (Aynı!)</text>\n  <text x="570" y="136" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">Ağırlık (G) = 20 N (6\'da 1\'i)</text>\n  <text x="570" y="166" text-anchor="middle" font-size="11" fill="#334155">120 N ÷ 6 = 20 N</text>\n  <text x="570" y="192" text-anchor="middle" font-size="11" fill="#475569">Dinamometre yayı az uzar</text>\n  <text x="570" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">(Örn: 1 bölmeli uzama)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÜNYA ÜZERİNDE KONUMA GÖRE AĞIRLIK DEĞİŞİMİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Deniz Seviyesi ve Yükseklik İlişkisi</text>\n  <polygon points="60,210 130,110 200,210" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="130" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">Dağ Zirvesi (Merkeze Uzak)</text>\n  <text x="130" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Deniz Seviyesi (Merkeze Yakın)</text>\n  <text x="255" y="120" text-anchor="middle" font-size="11" fill="#334155">Yukarı çıkıldıkça</text>\n  <text x="255" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">yer çekimi AZALIR,</text>\n  <text x="255" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">ağırlık AZALIR.</text>\n  <text x="255" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kütle ise DEĞİŞMEZ!</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Ekvator ve Kutuplar İlişkisi</text>\n  <ellipse cx="445" cy="150" rx="52" ry="42" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <line x1="393" y1="150" x2="497" y2="150" stroke="#dc2626" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="445" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Kutup (Basık - Yakın)</text>\n  <text x="445" y="146" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">Ekvator (Şişkin)</text>\n  <text x="595" y="120" text-anchor="middle" font-size="11" fill="#334155">Ekvator\'dan Kutuplara</text>\n  <text x="595" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">gidildikçe çekim ARTAR,</text>\n  <text x="595" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">ağırlık ARTAR.</text>\n  <text x="595" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Bilim Tarihi: Bîrûnî &amp; Hâzinî</text>\n  <text x="595" y="205" text-anchor="middle" font-size="10" fill="#475569">Merkeze çekim fikrinin öncüleri</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
